package textstats
import std.unittest.*
import std.unittest.testmacro.*
@Test class HoldoutOracle {
    @TestCase func checks(): Unit {
        @Expect(wordCount("a\tb\nc"), 3)
        @Expect(wordCount(" \t\r\n "), 0)
        @Expect(wordCount("\rhello\nworld\t"), 2)
        @Expect(wordCount("one"), 1)
        @Expect(wordCount(""), 0)
        @Expect(countExact("a b a", "a"), 2)
        @Expect(countExact("a\tb\na", "a"), 0)
        @Expect(countExact("a\tb", "a\tb"), 1)
    }
}

